$state=Get-Content 'C:\Users\user\Documents\Klei\OxygenNotIncluded\ai-bridge\live-profile-process.json' -Raw|ConvertFrom-Json;$p=Get-CimInstance Win32_Process -Filter "ProcessId=$($state.process_id)";$proc=Get-Process -Id ([int]$state.process_id);$h=(Get-FileHash -Algorithm SHA256 -LiteralPath $p.ExecutablePath).Hash.ToLower();if($p.ExecutablePath -cne $state.game_exe){throw 'path mismatch'};if(('sha256:'+$h) -cne $state.game_exe_sha256){throw 'hash mismatch'};[void]$proc.CloseMainWindow();if(-not $proc.WaitForExit(60000)){throw 'timeout'};if(Get-Process -Id ([int]$state.process_id) -ErrorAction SilentlyContinue){throw 'still running'};'stopped'
